<script setup lang="ts">
import { computed } from 'vue'
const props=defineProps<{width:number;height:number;cell:number;disabled?:boolean}>()
const emit=defineEmits<{change:[value:{width:number;height:number;cell:number} ]}>()
const columns=computed(()=>Math.ceil(props.width/(props.cell||1))),rows=computed(()=>Math.ceil(props.height/(props.cell||1)))
function update(key:string,event:Event){const value=Number((event.target as HTMLInputElement).value);const next={width:props.width,height:props.height,cell:props.cell};if(key==='columns')next.width=value*props.cell;else if(key==='rows')next.height=value*props.cell;else if(key==='width')next.width=value;else if(key==='height')next.height=value;else next.cell=value;emit('change',next)}
</script>
<template><fieldset class="scene-dimensions-fields" :disabled="disabled"><legend>Dimensões do cenário</legend><div><label>Largura do cenário (pixels)<input :value="width" type="number" min="128" max="16384" step="1" required @input="update('width',$event)"></label><label>Altura do cenário (pixels)<input :value="height" type="number" min="128" max="16384" step="1" required @input="update('height',$event)"></label><label>Colunas de quadrados<input :value="columns" type="number" :min="Math.ceil(128/(cell||1))" :max="Math.ceil(16384/(cell||1))" step="1" required @input="update('columns',$event)"></label><label>Linhas de quadrados<input :value="rows" type="number" :min="Math.ceil(128/(cell||1))" :max="Math.ceil(16384/(cell||1))" step="1" required @input="update('rows',$event)"></label></div><label>Tamanho da célula (pixels)<input :value="cell" type="number" min="32" max="128" step="1" required @input="update('cell',$event)"></label><p>{{ width }} × {{ height }} pixels · {{ columns }} × {{ rows }} quadrados<span v-if="width % cell || height % cell"> (a última linha ou coluna pode ser parcial)</span>.</p></fieldset></template>
<style scoped>.scene-dimensions-fields{border:1px solid #4e375f;border-radius:8px;margin:20px 0;padding:15px}.scene-dimensions-fields legend{color:#cbb1df;font-size:12px;padding:0 7px}.scene-dimensions-fields>div{display:grid;grid-template-columns:1fr 1fr;gap:0 14px}.scene-dimensions-fields label{font-size:11px;line-height:1.5;min-width:0}.scene-dimensions-fields input{min-width:0}.scene-dimensions-fields p{font-size:10px;color:#a98cbe;line-height:1.7;margin:10px 0 0}</style>
